BEGIN;
CREATE TABLE IF NOT EXISTS governed_rag_work_items(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,subject_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','approved','rejected','retired','erasure_pending','erased')),version INTEGER NOT NULL DEFAULT 1,input JSONB NOT NULL,result JSONB NOT NULL,uncertainty JSONB NOT NULL,created_by TEXT NOT NULL,approved_by TEXT,idempotency_key TEXT NOT NULL,request_hash CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS governed_rag_sources(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,source_ref TEXT NOT NULL,version TEXT NOT NULL,sha256 CHAR(64) NOT NULL,rights_basis TEXT NOT NULL,permission_policy JSONB NOT NULL,object_ref TEXT NOT NULL,deleted_at TIMESTAMPTZ,UNIQUE(tenant_id,source_ref,version),UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS governed_rag_chunks(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,source_id BIGINT NOT NULL,source_version TEXT NOT NULL,span TEXT NOT NULL,embedding_version TEXT NOT NULL,content_hash CHAR(64) NOT NULL,FOREIGN KEY(tenant_id,source_id) REFERENCES governed_rag_sources(tenant_id,id));
CREATE TABLE IF NOT EXISTS governed_rag_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,work_item_id BIGINT NOT NULL,actor_id TEXT NOT NULL,event_type TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),FOREIGN KEY(tenant_id,work_item_id) REFERENCES governed_rag_work_items(tenant_id,id));
CREATE TABLE IF NOT EXISTS governed_rag_outbox(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,work_item_id BIGINT NOT NULL,provider TEXT NOT NULL,operation TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','processing','delivered','failed','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,idempotency_key TEXT NOT NULL,request_hash CHAR(64) NOT NULL,claim_token TEXT,lease_expires_at TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,idempotency_key),FOREIGN KEY(tenant_id,work_item_id) REFERENCES governed_rag_work_items(tenant_id,id));
CREATE TABLE IF NOT EXISTS governed_rag_checkpoints(tenant_id TEXT NOT NULL,provider TEXT NOT NULL,cursor_value TEXT,source_version TEXT,last_success_at TIMESTAMPTZ,last_error TEXT,records_seen BIGINT NOT NULL DEFAULT 0,records_accepted BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,provider),CHECK(records_accepted<=records_seen));
ALTER TABLE governed_rag_work_items ADD COLUMN IF NOT EXISTS subject_id TEXT;
UPDATE governed_rag_work_items SET subject_id=created_by WHERE subject_id IS NULL;
ALTER TABLE governed_rag_work_items ALTER COLUMN subject_id SET NOT NULL;
CREATE INDEX IF NOT EXISTS governed_rag_subject_scope_idx ON governed_rag_work_items(tenant_id,subject_id,status,updated_at DESC);
CREATE OR REPLACE FUNCTION reject_governed_rag_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'governed_rag_events is append-only'; END $$;
DROP TRIGGER IF EXISTS governed_rag_events_append_only ON governed_rag_events;CREATE TRIGGER governed_rag_events_append_only BEFORE UPDATE OR DELETE ON governed_rag_events FOR EACH ROW EXECUTE FUNCTION reject_governed_rag_event_mutation();
COMMIT;
